function f130AliasAlternateExact(c:BuildingComponent){const e=F130_ALIAS_ALTERNATE;return c.city===e.city&&c.objectId===e.objectId&&c.partId===e.partId&&nativePaintSignature(c)==='2ac3339a'&&JSON.stringify(c.origin)===JSON.stringify(e.origin)&&JSON.stringify(c.componentGeometry)===JSON.stringify(e.componentGeometry)&&JSON.stringify(c.sourceFeature)===JSON.stringify(e.sourceFeature)&&c.batches.length===e.batches.length&&c.batches.every((b,bi)=>['positions','normals','indices','color'].every(k=>{const a=(b as any)[k],expected=(e.batches[bi]as any)[k];return a?.length===expected.length&&Array.from(a as ArrayLike<number>).every((v,j)=>Object.is(v,expected[j]));}));}

export function ownerF130GuardFailures(components:BuildingComponent[]){
 const rows:any[]=[];
 const firstDiff=(a:any,b:any,path:string):any=>{if(Object.is(a,b))return null;if(!a||!b||typeof a!=='object'||typeof b!=='object')return{path,expected:b,actual:a};const ak=Object.keys(a),bk=Object.keys(b);if(JSON.stringify(ak)!==JSON.stringify(bk))return{path,expectedKeys:bk,actualKeys:ak};for(const k of ak){const d=firstDiff(a[k],b[k],path+'.'+k);if(d)return d;}return null;};
 for(const id of F130_IDS){const list=components.filter(c=>c.city===id.city&&c.objectId===id.objectId&&c.partId===id.partId),expected=id.partId===F130_ALIAS_PART&&list.length===1&&F130_ALIAS_ALTERNATE.batches[0].color.every((v,j)=>Object.is(v,list[0].batches[0]?.color?.[j]))?F130_ALIAS_ALTERNATE:SOURCE[id.partId],failed:any[]=[];if(list.length!==1){rows.push({objectId:id.objectId,partId:id.partId,failed:[{field:'exactIdentityCount',expected:1,actual:list.length,otherCities:components.filter(c=>c.objectId===id.objectId&&c.partId===id.partId).map(c=>c.city)}]});continue;}const c=list[0];try{const signature=nativePaintSignature(c);if(signature!==id.signature)failed.push({field:'geometrySignature',expected:id.signature,actual:signature});}catch(e){failed.push({field:'geometrySignature',threw:String(e)});}
 for(const field of ['origin','componentGeometry','sourceFeature'])if(JSON.stringify((c as any)[field])!==JSON.stringify(expected[field]))failed.push({field,firstDifference:firstDiff((c as any)[field],expected[field],field),serializedDifferent:true});
 if(c.batches.length!==expected.batches.length)failed.push({field:'batches.length',expected:expected.batches.length,actual:c.batches.length});
 for(let bi=0;bi<Math.min(c.batches.length,expected.batches.length);bi++)for(const field of ['positions','normals','indices','color']){const a=(c.batches[bi]as any)[field],b=expected.batches[bi][field];if(a?.length!==b.length){failed.push({field:'batches.'+bi+'.'+field+'.length',expected:b.length,actual:a?.length,actualType:a?.constructor?.name});continue;}for(let i=0;i<b.length;i++)if(!Object.is(a[i],b[i])){failed.push({field:'batches.'+bi+'.'+field,index:i,expected:b[i],actual:a[i],expectedNegativeZero:Object.is(b[i],-0),actualNegativeZero:Object.is(a[i],-0),actualType:a?.constructor?.name});break;}}
 if(failed.length)rows.push({objectId:id.objectId,partId:id.partId,failed});
 }return rows;
}

export function ownerF130Reconstruction(components:BuildingComponent[]):{components:BuildingComponent[];stats:OwnerReconstructionStats}{const stats:OwnerReconstructionStats={objects:0,vertices:0,triangles:0,originalVertices:0,sourceRetained:true,actualVisualAccepted:false,components:[]};if(!components.some(c=>c.city==='cologne'&&ownerF130Identity(c)))return{components,stats};const ready=F130_IDS.every(i=>components.filter(c=>c.city===i.city&&c.objectId===i.objectId&&c.partId===i.partId).length===1&&components.some(c=>c.city===i.city&&c.objectId===i.objectId&&c.partId===i.partId&&nativePaintSignature(c)===i.signature&&((i.partId===F130_ALIAS_PART&&f130AliasAlternateExact(c))||(JSON.stringify(c.origin)===JSON.stringify(SOURCE[c.partId].origin)&&JSON.stringify(c.componentGeometry)===JSON.stringify(SOURCE[c.partId].componentGeometry)&&JSON.stringify(c.sourceFeature)===JSON.stringify(SOURCE[c.partId].sourceFeature)&&c.batches.length===SOURCE[c.partId].batches.length&&c.batches.every((b,bi)=>["positions","normals","indices","color"].every(k=>{const a=(b as any)[k],e=SOURCE[c.partId].batches[bi][k];return a?.length===e.length&&Array.from(a as ArrayLike<number>).every((v,j)=>Object.is(v,e[j]));}))))));if(!ready){stats.error='F130 exact native guard failed: '+JSON.stringify(ownerF130GuardFailures(components));return{components,stats};}return{components:components.map(c=>{if(c.city!=='cologne'||!ownerF130Identity(c))return c;const batches=DISPLAY[c.partId].map(b=>({...b,positions:[...b.positions],normals:[...b.normals],indices:[...b.indices],color:[...b.color],frames:[...b.frames],paint:[...b.paint],writeMask:[...b.writeMask]}));const vertices=batches.reduce((s,b)=>s+b.positions.length/3,0),triangles=batches.reduce((s,b)=>s+b.indices.length/3,0);if(vertices>0)stats.objects++;stats.vertices+=vertices;stats.triangles+=triangles;stats.originalVertices+=c.batches.reduce((s,b)=>s+b.positions.length/3,0);stats.components.push({objectId:c.objectId,partId:c.partId,sourcePartId:c.partId,patchSHA256:F130_RECONSTRUCTION_SHA,vertices,triangles,geometryRole:'owner-authorized-reconstruction'});return{...c,batches,displayEstimates:{...c.displayEstimates,F130Exterior:{sourceRetained:true,sourceOnlyAlias:vertices===0,patchSHA:F130_RECONSTRUCTION_SHA,originalSourcesRetained:true,sourceGetterGeometryUnchanged:true,originalNativeTrianglesRetained:true,sourceDescriptionAndDirectReferencesBound:true,photoSupportedGableFinialsAdded:4,wholeExteriorClaim:false,faceSpecificPlanAndPhotoPainting:true,localFacadeFrames:true}}};}),stats};}
export function ownerF130BaseMaterials(components:BuildingComponent[],paint:Float32Array,frames:Float32Array){let offset=0,objects=0,vertices=0;for(const c of components){const match=c.city==='cologne'&&ownerF130Identity(c)&&!!c.displayEstimates?.F130Exterior;if(match)objects++;for(const b of c.batches){const count=b.positions.length/3;if(match){const a=b as Batch;for(let j=0;j<count;j++)if(a.writeMask[j]){paint.set(a.paint.slice(j*4,j*4+4),4*(offset+j));frames.set(a.frames.slice(j*5,j*5+5),5*(offset+j));vertices++;}}offset+=count;}}return{objects,vertices,actualVisualAccepted:false};}
